def open_maybe_gz(path):
    # Galaxy may bind a gzip dataset under a neutral filename, so detect the
    # gzip magic bytes instead of relying on the file extension.
    with open(path, "rb") as probe:
        magic = probe.read(2)
    if magic == b"\x1f\x8b":
        return gzip.open(path, "rt")
    return open(path, "rt")


